import{_ as n,o as h,c as i,a5 as r}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"08 — Subscription & Billing","description":"","frontmatter":{},"headers":[],"relativePath":"ba/08-subscription-billing.md","filePath":"ba/08-subscription-billing.md"}'),a={name:"ba/08-subscription-billing.md"};function e(c,t,o,g,d,s){return h(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="_08-—-subscription-billing" tabindex="-1">08 — Subscription &amp; Billing <a class="header-anchor" href="#_08-—-subscription-billing" aria-label="Permalink to &quot;08 — Subscription &amp; Billing&quot;">​</a></h1><p>&gt; <a href="./00-overview.html">&lt;&lt; Về Overview</a></p><h2 id="quyet-đinh-hien-hanh-—-2026-10-19" tabindex="-1">Quyết định hiện hành — 2026-10-19 <a class="header-anchor" href="#quyet-đinh-hien-hanh-—-2026-10-19" aria-label="Permalink to &quot;Quyết định hiện hành — 2026-10-19&quot;">​</a></h2><p><strong>Bổ sung đã chốt 2026-10-20:</strong> hạn mức fallback hệ thống 10 credit/thành viên/kỳ; Owner được đặt mặc định Agency hoặc mức riêng để ghi đè. Nội dung/hashtag tính theo yêu cầu thành công, ảnh/video theo từng sản phẩm thành công (thành công một phần chỉ tính phần thành công). Ví dụ 3 credit/ảnh không phải giá đã chốt. Subscription hết hạn vẫn reset hạn mức hàng tháng theo anchor chu kỳ cũ; credit mua thêm không hết hạn. Cấp số dư qua đầu nối Subscription/Payment có chống trùng, không tự suy thanh toán từ trạng thái ACTIVE.</p><p>Chủ sản phẩm chốt quản lý credit theo <strong>thành viên trong một Agency</strong>, không chỉ Creator:</p><ul><li>Owner/Manager/Creator dùng AI; Client không dùng. Owner không có hạn mức cá nhân nhưng vẫn bị giới hạn bởi số dư chung Agency.</li><li>Owner đặt hạn mức mặc định Agency và ghi đè từng thành viên; tổng hạn mức có thể lớn hơn quỹ chung vì đây là trần cá nhân, không phải chia ví. Mặc định hệ thống đã chốt là 10 credit/thành viên/kỳ; không phải khoản cấp tiền.</li><li>Usage reset theo kỳ subscription; giữ nguyên hạn mức cấu hình. Credit Plan không rollover; dùng trước credit mua thêm. Credit mua thêm không hết hạn và vẫn dùng được khi subscription hết hạn/hủy.</li><li>Admin cấu hình giá từng thao tác; giữ giá phiên bản tại thời điểm nhận yêu cầu AI. Giá mới không thay giá tác vụ đang chạy.</li><li>Subscription/Payment do thành viên khác phụ trách; đợt này quản lý một Agency, không tự cấp nhân đôi định mức subscription của Owner sang các Agency khác.</li></ul><p>Các mục Creator/tháng bên dưới là mô tả lịch sử; quyết định này ưu tiên khi khác nhau. Xem <a href="./../feature/subscription-billing/member-credit/spec.html">đặc tả và trạng thái triển khai</a>. DA-974 hiện đã có cấu hình, báo cáo và giữ/quyết toán Credit trên các API AI theo đơn giá thao tác đã chốt lúc gửi. Thanh toán tự động và tính phí theo token/tài nguyên self-host Vast chưa nằm trong phần triển khai này.</p><h2 id="danh-sach-fr-đay-đu-3-9-1-–-3-9-7" tabindex="-1">Danh sách FR đầy đủ (3.9.1 – 3.9.7) <a class="header-anchor" href="#danh-sach-fr-đay-đu-3-9-1-–-3-9-7" aria-label="Permalink to &quot;Danh sách FR đầy đủ (3.9.1 – 3.9.7)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>FR</th><th>Tên</th><th>Role</th><th>Mô tả</th></tr></thead><tbody><tr><td>3.9.1</td><td>Upgrade Plan</td><td>USER</td><td>Default user mới tạo = gói <strong>Basic</strong>. Upgrade lên Pro/Enterprise để tạo nhiều workspace, nhiều credit AI, dùng tính năng nâng cao</td></tr><tr><td>3.9.2</td><td>Downgrade Plan</td><td>OWNER</td><td>Hủy gói khi không còn nhu cầu</td></tr><tr><td>3.9.3</td><td>Make Payment (PayOS)</td><td>USER</td><td>Tạo Transaction cho upgrade gói, mua thêm credit — <strong>tuân thủ ACID</strong></td></tr><tr><td>3.9.4</td><td>View Invoice History</td><td>OWNER</td><td>Xem lịch sử giao dịch tài khoản</td></tr><tr><td>3.9.5</td><td>View AI Credit Tracking</td><td>CREATOR, OWNER</td><td>Giám sát lượng credit Creator đã dùng cho AI feature trong tháng (tạo ảnh, content, video)</td></tr><tr><td>3.9.6</td><td>Buy Credit</td><td>OWNER</td><td>Mua thêm credit khi hết credit trong gói Pro/Enterprise</td></tr><tr><td>3.9.7</td><td>Set Credit</td><td>OWNER</td><td>Owner đặt hạn mức tiêu credit cho Creator</td></tr></tbody></table><h2 id="ghi-chu-nghiep-vu-quan-trong" tabindex="-1">Ghi chú nghiệp vụ quan trọng <a class="header-anchor" href="#ghi-chu-nghiep-vu-quan-trong" aria-label="Permalink to &quot;Ghi chú nghiệp vụ quan trọng&quot;">​</a></h2><h3 id="gan-plan-voi-agency-khong-phai-workspace" tabindex="-1">Gắn Plan với Agency, không phải Workspace <a class="header-anchor" href="#gan-plan-voi-agency-khong-phai-workspace" aria-label="Permalink to &quot;Gắn Plan với Agency, không phải Workspace&quot;">​</a></h3><ul><li>Plan (Basic/Pro/Enterprise) là thuộc tính của <strong>User/Owner</strong>, ảnh hưởng số lượng Workspace được tạo và credit AI khả dụng — không phải mua riêng theo từng Workspace.</li><li>Đây khớp với mô hình 3 tầng ở <a href="./01-organization-structure.html">01-organization-structure.md</a>: User là Owner của Agency, Agency chứa nhiều Workspace — Plan giới hạn ở tầng User/Owner sẽ tác động toàn bộ Agency của họ.</li></ul><h3 id="acid-cho-make-payment-3-9-3" tabindex="-1">ACID cho Make Payment (3.9.3) <a class="header-anchor" href="#acid-cho-make-payment-3-9-3" aria-label="Permalink to &quot;ACID cho Make Payment (3.9.3)&quot;">​</a></h3><ul><li>Yêu cầu kỹ thuật rõ ràng: giao dịch thanh toán phải đảm bảo tính toàn vẹn ACID (Atomicity, Consistency, Isolation, Durability) — quan trọng vì liên quan tiền thật qua PayOS.</li></ul><h3 id="credit-ai-—-2-lop-kiem-soat" tabindex="-1">Credit AI — 2 lớp kiểm soát <a class="header-anchor" href="#credit-ai-—-2-lop-kiem-soat" aria-label="Permalink to &quot;Credit AI — 2 lớp kiểm soát&quot;">​</a></h3><ul><li><strong>View AI Credit Tracking</strong> (3.9.5): cả Creator (xem mình đã dùng bao nhiêu) và Owner (giám sát toàn Agency) đều xem được.</li><li><strong>Set Credit</strong> (3.9.7): CHỈ Owner mới đặt được hạn mức tiêu credit cho từng Creator — đây là cơ chế kiểm soát chi phí AI nội bộ Agency, ngăn 1 Creator dùng vượt quá ngân sách được cấp. <strong>[CONFIRMED 2026-09-17]</strong> Hạn mức là <strong>cứng (hard limit)</strong> — khi Creator dùng hết credit được cấp, hệ thống <strong>chặn hẳn</strong> thao tác AI tiếp theo của Creator đó (không phải chỉ cảnh báo/soft warning), cho tới khi Owner cấp thêm hoặc reset hạn mức tháng sau.</li><li><strong>Buy Credit</strong> (3.9.6): CHỈ Owner mua thêm — Creator không tự mua credit cho mình.</li></ul>',16)])])}const m=n(a,[["render",e]]);export{u as __pageData,m as default};
